window.RP_SESSION={"id":"S-1d96d05649b6","messages":[{"id":"RP-III-0151346","time":"2026-08-18T15:40:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사이먼은 지금 뒷골목에 쓰러져 있다. 대단한 이유는 아니었다. 평범하게 평범한 소년인척하는 강도를 만났고, 평범하게 칼에 찔렸다. 어린아이라고 방심했던 탓이다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151347","time":"2026-08-18T15:40:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151348","time":"2026-08-18T15:40:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'사이먼 포레스트'의 의지 판정 :\n[8] + [3] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0151349","time":"2026-08-18T15:40:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아야 내 목.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151350","time":"2026-08-18T15:42:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 목소리가 나오지 않지만, 저 불쌍한 아이를 위한 기도 정도는 빌 수 있겠지.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151351","time":"2026-08-18T15:44:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 고결하신 희생의 신이시여, 제가 여기서 죽사오니 저를 당신의 품에 안겨주시옵시고 저 이를 축복하소서. 저와 같은 최후를 맞이 하는 이가 줄어들게 하소서. 빈 배에 삿된것이 차지할 자리가 없게 하소서.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151352","time":"2026-08-18T15:45:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"  [자, 이제 내 손을 잡으렴.]","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151353","time":"2026-08-18T15:47:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아, 그러고보니 아직 철자를 다 알려주지도 못하였는데. 아쉽구나. 부끄럽지만 모두를 사랑한다 말하지 못한 것도. 몸이 무너져 내린다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151354","time":"2026-08-18T15:47:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그리하여 그 자리에 남은 것은 미련한 진흙덩이 뿐이었다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151355","time":"2026-08-18T15:47:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!졸업 사이먼 포레스트","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151356","time":"2026-08-18T15:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"['사이먼 포레스트' 의 여정을 마치고 모험에서 떠납니다. 정말 그렇게 하시겠습니까?]\n\n[예] / [아니오]\n\n※ 모험이 종료된 캐릭터는 복귀할 수 없습니다.","characters":[]},{"id":"RP-III-0151357","time":"2026-08-18T15:47:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"예","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151358","time":"2026-08-18T15:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"당신의 여정은 결코 헛되지 않았습니다.\n\n수많은 이들이 당신의 이름을 알지는 못하겠지만,\n적어도 몇몇 이들은 당신을 기억할 것입니다.\n\n함께 검을 들었던 동료,\n같은 식탁에서 웃음을 나누었던 이들,\n그리고 당신의 손길을 한 번쯤은 빌렸던 사람들까지.\n\n누군가는 당신을,\n제 몫의 싸움을 다해낸 성실한 모험가로 기억할 것이고\n\n누군가는 당신을,\n비록 목표의 끝에 도달하진 못했지만 그럼에도 끊임없이 나아갔던 사람으로 떠올릴 것입니다.\n\n당신의 이름은 세상을 뒤흔들 만큼 크지 않았지만,\n\n그럼에도 분명 누군가의 기억 속에서는\n\n작지 않은 의미로 남습니다.\n\n그리고 마침내,\n당신은 모든 것을 마치고 영혼길에 오릅니다.\n\n수많은 날들 속에서 쌓아온 발걸음과\n그 끝에서 비로소 내려놓는 숨은\n\n조용히, 그러나 분명하게\n\n당신의 삶이 있었음을 증명합니다.","characters":[]},{"id":"RP-III-0151359","time":"2026-08-18T15:48:00+09:00","room":"RP III","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0151360","time":"2026-08-18T15:48:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
